def cheapest_route(n, flights, src, dst, k):
    cost = [float('inf')] * n
    cost[src] = 0
    for _ in range(k + 1):
        nxt = cost[:]
        for frm, to, price in flights:
            if cost[frm] + price < nxt[to]:
                nxt[to] = cost[frm] + price
        cost = nxt
    return -1 if cost[dst] == float('inf') else cost[dst]
